const combatAudio=createCombatAudio();let testUnlocked=false;
function movementInput(){return{x:input.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),z:input.z+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)};}
function requestRoll(){if(!playing||panel.open||evolving)return false;const v=movementInput();return world.roll(v.x,v.z);}

const $=id=>document.getElementById(id),panel=$('panel'),input={x:0,z:0},keys=new Set();
let scenePromise=null,launchPromise=null;
async function ensureScene(){if(scene)return scene;if(scenePromise)return scenePromise;PhantomLoading.begin('正在準備洞穴戰場');scenePromise=(async()=>{try{PhantomLoading.stage('讀取旅人、武器與戰鬥動作',.12);for(const [src,ready] of [['../vendor/three.min.js',()=>!!globalThis.THREE],['../vendor/GLTFLoader.js',()=>!!globalThis.THREE?.GLTFLoader]]){if(!ready())await new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=resolve;el.onerror=()=>{el.remove();reject(Error('引擎讀取失敗，請重試'));};document.head.append(el);});}PhantomLoading.install();const {createScene}=await import('./scene.js?v=20261025-v22');scene=await createScene($('world'),{spirits:Object.values(data.spirits),catalog:data.catalog,onSelect:id=>{if(playing&&!panel.open)world.select(id);},onError:e=>toast('素材問題：'+(e.message||e))});feedback=createFeedback(scene);data.config.rollDuration=scene.metrics.rollDuration;PhantomLoading.stage('戰場準備完成',.97);PhantomLoading.end();return scene;}catch(e){scenePromise=null;PhantomLoading.fail('場景讀取失敗，請重試');throw e;}})();return scenePromise;}
let tutorial=null;
let shopTab='items',trainingId='';
let store,data,world,scene,preview,playing=false,frame=0,lastTime=0,lastSave=0,lastHud=0,toastTimer,modalType='',pendingAction=false,ball='ball-basic',autoCapture=false,autoCaptureAt=0,capturePendingPoints=0,feedback=null,captureEpoch=0,evolving=false,summonController=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(text){if(panel?.open){let note=$('panelNotice');if(!note){note=document.createElement('p');note.id='panelNotice';note.className='panel-notice';note.setAttribute('role','status');$('panelBody').prepend(note);}note.textContent=text;}$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function picture(id){return '../'+(data.art[id]?.image||data.art[id]?.path||'portraits/'+id+'.png');}
function name(id){if(id==='ore')return '洞穴礦石';return data.spirits[id]?.name||ITEMS[id]?.name||WEAPONS[id]?.name||id;}
function safe(fn){return(...args)=>{try{return fn(...args);}catch(e){toast(e.message);console.error(e);}};}
function action(fn){if(pendingAction)return;pendingAction=true;try{fn();}catch(e){toast(e.message);}finally{pendingAction=false;}}
function open(title,html,type='menu',closable=true){combatAudio.stop();modalType=type;panel.dataset.view=type;$('panelTitle').textContent=title;$('panelBody').innerHTML=html;$('closePanel').hidden=!closable;if(!panel.open)panel.showModal();keys.clear();input.x=input.z=0;}
function close(){if(evolving)return;if(modalType.startsWith('test'))testUnlocked=false;if(['upgrade','cleared','defeat','weapon-unlock'].includes(modalType))return;summonController?.dispose();summonController=null;panel.close();modalType='';}
function button(text,fn,container=$('panelBody'),className=''){const b=document.createElement('button');b.textContent=text;b.className=className;b.onclick=safe(fn);container.append(b);return b;}
function originalProgress(){try{return JSON.parse(localStorage.getItem('phantom_journey_v1')||'{}');}catch{return {};}}
function syncCostume(){if(!world)return;world.setCostume(costumeFor(originalProgress()).id);if(preview)preview.costumeId=world.costume.id;const summary=$('costumeSummary');if(summary){summary.textContent=world.costume.name;summary.title=world.costume.description;}}
function costumeNote(){syncCostume();const c=world.costume;return '<details class="costume-note"><summary>服裝效果 · '+esc(c.name)+'</summary><p>'+esc(c.description)+'</p><small>沿用主遊戲冒險衣櫃目前穿著的服裝；回城換裝後即更新。</small></details>';}
function openTestGate(){testUnlocked=false;open('測試模式','<p class="compact-note">輸入測試密碼後選擇功能。</p><form id="testGateForm" class="test-gate"><label for="testPassword">測試密碼</label><input id="testPassword" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off" required><p id="testGateError" role="status"></p><button type="submit" class="primary">進入測試</button></form>','test-gate');$('testGateForm').onsubmit=async e=>{e.preventDefault();const field=$('testPassword'),value=field.value;field.value='';try{const valid=await verifyTestPassword(value);if(modalType!=='test-gate'||!panel.open)return;if(valid){testUnlocked=true;showTestMenu();}else{$('testGateError').textContent='密碼不正確，請重新輸入';field.focus();}}catch{$('testGateError').textContent='無法驗證密碼，請重新整理後再試';}};setTimeout(()=>$('testPassword')?.focus(),0);}
function showTestMenu(){if(!testUnlocked)return openTestGate();open('測試功能','<p class="compact-note">選擇要執行的測試操作。</p><div id="testChoices"></div>','test-menu');button('重置＋5000點＋2把武器',resetTest,$('testChoices'),'quiet-danger');const choose=button('測試用・自由選擇出戰幻靈',testPetMenu,$('testChoices'));choose.disabled=!playing||world.run?.status!=='active';button('返回探險補給',bag);}
function testPetMenu(){if(!testUnlocked){openTestGate();return;}const list=dexSpecies(data.spirits,data.catalog,data),active=world.run?.pets[world.run.activePet];if(!active)return;open('測試用・自由選擇出戰幻靈','<p class="compact-note">只替換本局出戰寵物，從戰局 Lv.1 滿血開始。保留主遊戲衣櫃、卡片、永久收藏與編組。</p><label class="test-pet-select">選擇幻靈<select id="testPetSelect">'+CARD_GROUPS.map(g=>'<optgroup label="'+g.name+'">'+list.filter(p=>(p.cardFrame||'yellow')===g.id).map(p=>'<option value="'+p.id+'" '+(p.id===active.speciesId?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</optgroup>').join('')+'</select></label><div class="test-pet-preview" id="testPetPreview"></div><div id="testPetActions"></div>','test-pets');const update=()=>{const id=$('testPetSelect').value;$('testPetPreview').innerHTML='<img src="'+picture(id)+'" alt="'+esc(name(id))+'"><div><strong>'+esc(name(id))+'</strong><p>'+esc(passiveAt(id,data.passives,growthOf(store.state,id).level).description)+'</p></div>';};$('testPetSelect').onchange=update;update();button('套用為本局出戰寵物',()=>{chooseTestPet(store,data,$('testPetSelect').value);world.syncHealth();hud();bag();toast('測試寵物已替換，關閉視窗即可繼續探險');},$('testPetActions'),'primary');button('返回探險補給',bag,$('testPetActions'));}
function lobby(){syncCostume();summonController?.dispose();summonController=null;playing=false;document.body.classList.remove('playing');$('lobby').hidden=false;$('hud').hidden=true;$('heroOverheadHealth').hidden=true;const s=store.state,last=s.lastResult;$('lastRun').hidden=!last;if(last)$('lastRun').innerHTML='<span>上次 '+formatTime(last.time)+' · 擊破 '+last.kills+' · 捕捉 '+last.captures+'</span>';$('points').textContent='✦ '+s.points.toLocaleString()+' 點';$('partyPreview').innerHTML=[0,1,2].map(i=>s.team[i]?'<div class="preview-card"><img class="portrait" src="'+picture(s.team[i])+'" alt="'+esc(name(s.team[i]))+'"><span>'+esc(name(s.team[i]))+'</span></div>':'<div class="preview-card"><div class="empty-card">◇</div><span>尚未召喚</span></div>').join('');$('start').textContent=s.starterClaimed?'開始新挑戰':'免費獲得三隻幻靈';$('start').hidden=false;$('resume').hidden=!s.run||s.run.status==='defeated';$('resume').textContent='繼續上次戰局';$('lobbyHint').textContent=s.starterClaimed?'帳號進度自動存檔 · 新挑戰由第1波開始':'隨機三隻基礎幻靈，附靈核球與藥水。';preview=createRun({...s,equipped:s.equipped},data);preview.costumeId=world.costume.id;}

function enter(resume=false){syncCostume();if(!store.state.starterClaimed){action(()=>{const result=claimStarter(store,eligiblePool(data.pool,originalProgress(),{standalone:true}));lobby();showRewards(result.value,'初次相遇');});return;}if(store.state.team.length!==3)throw Error('請先編組三隻幻靈');if(!scene){if(launchPromise)return launchPromise;$('start').disabled=$('resume').disabled=true;launchPromise=ensureScene().then(()=>enter(resume)).catch(e=>{console.error(e);toast(e.message);}).finally(()=>{launchPromise=null;$('start').disabled=$('resume').disabled=false;});return launchPromise;}if(!resume||!world.run||world.run.status==='defeated'){if(world.run)finish(world.run.status==='defeated'?'主角陣亡':'重新挑戰');scene?.resetTransient();feedback?.clear();world.start();}playing=true;document.body.classList.add('playing');$('lobby').hidden=true;$('hud').hidden=false;panel.close();modalType='';lastSave=performance.now();hud();toast(resume?'已繼續上次戰局':'新挑戰開始 · 第1波');tutorial?.begin('combat');}

function showRewards(rewards,title='命運共鳴'){summonController?.dispose();const token=Date.now();open(title,summonMarkup(rewards,picture)+'<button id="skipSummon" class="primary">跳過動畫，揭曉獎勵</button>','summon',false);const reveal=()=>{if(modalType!=='summon'||panel.dataset.summon!==String(token))return;summonController?.dispose();summonController=null;revealRewards(rewards,title);};panel.dataset.summon=token;$('skipSummon').onclick=reveal;$('panelBody').querySelector('.summon-v07').addEventListener('summoncomplete',reveal,{once:true});summonController=startSummon(panel,rewards,picture);}
function wallet(){return '<div class="wallet-strip"><span>'+icon('points')+'持有點數</span><strong>'+store.state.points.toLocaleString()+'<small>點</small></strong></div>';}
function revealRewards(rewards,title='本次獲得'){
 const groups=groupRewards(rewards),total=rewards.reduce((n,r)=>n+(r.quantity||1),0);
 open(title,'<div class="reward-summary"><span>獲得 <b>'+total+'</b> 份獎勵 · '+groups.length+' 種</span><span>剩餘 <b>'+store.state.points.toLocaleString()+'</b> 點</span></div><div class="reward-list">'+groups.map(r=>{const spirit=r.kind==='spirit',weapon=r.kind==='weapon',color=spirit||weapon?r.color||'yellow':'supply';return '<article class="reward-entry '+color+'" data-reward="'+r.id+'"><div class="reward-portrait">'+(spirit?'<img src="'+picture(r.id)+'" alt="'+esc(name(r.id))+'">':itemPicture(r.id))+'</div><div class="reward-copy"><small>'+(spirit?({yellow:'黃卡',purple:'紫卡',red:'紅卡'})[color]:weapon?'永久武器':r.kind==='material'?'素材':'道具')+'</small><strong>'+esc(name(r.id))+'</strong><p>'+(spirit?(r.duplicate?'重複 → 羈絆素材':'新增幻靈'):weapon?(r.duplicate?'重複武器 → 退回 '+(r.refund*r.quantity)+' 點':'已加入永久武器庫'):r.kind==='material'?'已存入材料倉庫':'已存入背包')+'</p></div><b class="reward-qty">×'+r.quantity+'</b></article>';}).join('')+'</div>','rewards');
 button('收下全部獎勵',close,$('panelBody'),'primary reward-confirm');
}
function prepareLobbyAction(next){const r=world.run;if(!r)return true;if(r.status==='defeated'){finish('主角陣亡');return true;}open('探險尚未結束','<p>目前進度 '+formatTime(r.time)+'。可繼續探險，或結算後召喚與更換編組。</p><p class="compact-note">結算會保留點數、收藏、永久培育與未使用道具；本局增幅與臨時武器於新挑戰重新開始。</p>','checkpoint-action');button('繼續上次探險',()=>enter(true),$('panelBody'),'primary');button('結算並繼續',()=>{finish('主畫面結算');next();},$('panelBody'));button('取消',close);return false;}
function gacha(){if(!prepareLobbyAction(gacha))return;const pool=eligiblePool(data.pool,originalProgress(),{standalone:true});let error='';try{validatePool(pool);}catch(e){error=e.message;}
 open('洞穴轉蛋機',wallet()+'<div class="gacha-intro"><button class="gacha-machine compact-summoner" aria-label="轉動轉蛋機">'+itemPicture('summon-machine')+'</button><div><strong>尋找下一位夥伴</strong><p>幻靈・補給・素材<br>新增本局幻靈經驗 ×2</p></div></div><div class="draw-actions" id="drawActions"></div><p class="pity-line">保底進度 <b>'+store.state.pity+' / 99</b> · 第100抽必中幻靈</p><details class="pool-details"><summary>獎池與機率</summary><p>幻靈20%（黃12%・紫6%・紅2%）<br>永久武器10%・補給20%・素材20%・技能15%・能力15%<br>武器池各把等機率；1000點武器為紅光，其他武器為紫光。重複永久武器退回該抽100點。<br>技能池含幻靈經驗雙倍晶：使用後本局經驗×2，不疊加。<br>保底色階：黃60%／紫30%／紅10%。</p></details>'+(error?'<p class="notice">'+esc(error)+'</p>':''),'gacha');
 for(const n of[1,10]){const b=button((n===1?'召喚一次':'召喚十次')+' · '+(n*100).toLocaleString()+' 點',()=>action(()=>{const result=draw(store,pool,n);lobby();showRewards(result.value);}),$('drawActions'),n===10?'primary':'');b.disabled=!!error||store.state.points<n*100;}
 $('panelBody').querySelector('.gacha-machine').onclick=()=>{const b=$('drawActions').querySelector('button');if(b.disabled)toast(error||'點數不足');else b.click();};
}
function playHistory(){const records=store.state.playHistory||[];open('遊玩紀錄','<p class="compact-note">進度自動儲存・最近100筆旅程紀錄</p><div class="history-list">'+(records.length?records.map(r=>'<article><strong>'+esc(r.reason)+'</strong><span>深度 '+r.depth+' · '+formatTime(r.time)+' · 擊破 '+r.kills+' · 捕捉 '+r.captures+'</span><small>'+new Date(r.at).toLocaleString('zh-TW')+'</small></article>').join(''):'<p>尚未結束過探險。進行中的戰局可直接繼續。</p>')+'</div>','history');}

function team(){if(!prepareLobbyAction(team))return;open('幻靈編組',wallet()+rosterNav('team')+`<p class="muted">選取三隻不同的基礎幻靈。第一格出戰，能力常駐於自身；存活備戰時另提供隊伍數值加成，命中效果僅由出戰本人觸發。</p><div class="grid" id="teamGrid"></div>`,'team');wireRoster();for(const id of store.state.owned){const tile=document.createElement('article');tile.className='tile';tile.innerHTML=`<img src="${picture(id)}" alt="${esc(name(id))}"><strong>${esc(name(id))}</strong><p>${esc(data.passives[id]?.description)}</p>`;button(store.state.team.includes(id)?`編組 ${store.state.team.indexOf(id)+1} · 移除`:'加入隊伍',()=>{store.transact(store.newId('team'),s=>{if(s.team.includes(id))s.team=s.team.filter(x=>x!==id);else if(s.team.length<3)s.team.push(id);else throw Error('請先移除一隻幻靈再加入');});lobby();team();},tile);$('teamGrid').append(tile);}}
function framedCard(id){const species=data.spirits[id],stats=basicStats(species,store.state),passive=passiveAt(id,data.passives,stats.level),number=data.catalog.entries.find(e=>e.id===id)?.number||'—';return '<article class="dex-card" data-frame="'+(species.cardFrame||'yellow')+'"><div class="dex-visual"><img class="dex-art" src="'+picture(id)+'" alt="'+esc(name(id))+'"><img class="dex-frame" src="../assets/cards/frame.png" alt=""></div><h3 class="dex-name">'+esc(name(id))+'</h3><span class="dex-number">No.'+number+'</span><div class="dex-info"><p class="dex-element">'+esc(species.type)+' · 培育 Lv.'+stats.level+'</p><div class="dex-stats"><span>HP '+stats.hp+'</span><span>攻 '+stats.attack+'</span><span>防 '+stats.defense+'</span></div><p class="dex-passive"><span>'+passive.slotCount+' 欄 · '+esc(passiveSummary(passive))+'</span></p></div></article>';}

function wireEvolutionLinks(){for(const b of $('panelBody').querySelectorAll('[data-evolution-id]'))b.onclick=()=>showSpiritSkills(b.dataset.evolutionId);}
function collection(){
 const normal=dexSpecies(data.spirits,data.catalog,data);
 open('幻靈圖鑑',wallet()+'<p class="compact-note">黃卡 → 紫卡 → 紅卡。點卡片查看招式與完整進化關係。</p>'+evolutionMechanics()+'<nav class="dex-color-nav" aria-label="卡色分類">'+CARD_GROUPS.map(c=>'<button data-color="'+c.id+'">'+c.name+'</button>').join('')+'</nav><div class="dex-grid" id="dexGrid"></div>','collection');
 for(const group of CARD_GROUPS){
  const members=normal.filter(s=>(s.cardFrame||'yellow')===group.id),heading=document.createElement('h3');heading.id='dex-'+group.id;heading.className='dex-color-heading';heading.dataset.color=group.id;heading.style.setProperty('--rarity',({yellow:'#e6cb87',purple:'#cf9dff',red:'#ff8c9f'})[group.id]);heading.innerHTML=group.name+'<small>'+members.length+' 種 · '+({yellow:'1 種被動',purple:'2 種被動',red:'3 種被動'})[group.id]+'</small>';$('dexGrid').append(heading);
  for(const species of members){const id=species.id,g=growthOf(store.state,id),owned=store.state.owned.includes(id),root=familyRoot(id),base=isTrainingBase(id),eligible=base&&ownsFamily(store.state,id),tile=document.createElement('section');tile.dataset.species=id;tile.dataset.color=group.id;tile.className='dex-tile'+(owned?' owned':' unowned');tile.innerHTML='<button class="dex-open" aria-label="查看'+esc(name(id))+'">'+framedCard(id)+'</button><p class="dex-evolution">'+esc(evolutionSummary(id,data))+'</p><div class="dex-growth"><div class="dex-level"><span>'+(base?'家族永久培育':'繼承 '+esc(name(root)))+' Lv.'+g.level+'</span><small>'+g.xp+' / '+xpRequired(g.level)+' XP</small></div><div class="growth-track"><i style="width:'+(g.xp/xpRequired(g.level)*100)+'%"></i></div><p>'+(g.level>=50?'被動已達最高培育加成':'下一次被動變化：Lv.'+Math.min(50,(Math.floor(g.level/10)+1)*10))+'</p></div>';tile.querySelector('.dex-open').onclick=()=>showSpiritSkills(id);if(base){const b=button(eligible?(g.level>=50?'培育已滿級':'+25 XP · '+xpPrice(g.level)+' 點'):'尚未持有此家族',()=>action(()=>{buyExperience(store,id);if(!playing)lobby();collection();}),tile,'dex-upgrade');b.disabled=!eligible||g.level>=50||store.state.points<xpPrice(g.level);}else tile.insertAdjacentHTML('beforeend','<p class="compact-note dex-inherit">由'+esc(name(root))+'統一培育，能力加成同步繼承</p>');$('dexGrid').append(tile);}
 }
 for(const b of $('panelBody').querySelectorAll('[data-color]'))if(b.tagName==='BUTTON')b.onclick=()=>document.getElementById('dex-'+b.dataset.color).scrollIntoView({behavior:'smooth',block:'start'});
}
